solution.solution.py:
class FakeClock:
    def __init__(self, start=0.0):
        self._time = start

    def now(self):
        return self._time

    def advance(self, seconds):
        if seconds < 0:
            raise ValueError("time cannot go backwards")
        self._time += seconds


def is_expired(session, clock):
    return clock.now() >= session["started"] + session["timeout"]

unitTests:
@test("now starts at the start value")
def _():
    check_eq(FakeClock(5.0).now(), 5.0)
    check_eq(FakeClock().now(), 0.0)

@test("advance moves the time")
def _():
    c = FakeClock(10)
    c.advance(2.5)
    c.advance(1)
    check_eq(c.now(), 13.5)

@test("advance refuses going backwards")
def _():
    check_raises(ValueError, FakeClock().advance, -1)

@test("a session expires exactly at started + timeout")
def _():
    c = FakeClock(100)
    s = {"started": 100, "timeout": 30}
    check(not is_expired(s, c))
    c.advance(29.9)
    check(not is_expired(s, c))
    c.advance(0.1)
    check(is_expired(s, c))

@test("any object with now() works")
def _():
    class Fixed:
        def now(self):
            return 1000
    check(is_expired({"started": 0, "timeout": 10}, Fixed()))

